Ben has been given the following pseudocode function:

```
int func(int arr[], int n, int k) {
    int res[] = new int[n + 1];
    res[0] = 0;
    res[1] = arr[0];
    for (int i = 2; i <= n; i++)
        res[i] = res[i - 1] + arr[i - 1];
    PriorityQueue<Integer> p = new PriorityQueue<Integer>();   // min-heap
    for (int i = 1; i <= n; i++) {
        for (int j = i; j <= n; j++) {
            int res1 = res[j] - res[i - 1];
            if (p.size() < k)
                p.add(res1);
            else {
                if (p.peek() < res1) {
                    p.poll();
                    p.add(res1);
                }
            }
        }
    }
    return p.poll();
}
```

